# 按类别汇总流水金额。rows 为 (category, amount_cents) 序列。
# 返回 {category: 累计金额}，未出现的类别不出现在结果中。


def total_by_category(rows):
    """聚合每个类别的金额总和。"""
    totals = {}
    for category, amount_cents in rows:
        # 错误：用赋值覆盖，同一类别只保留最后一条记录。
        totals[category] = amount_cents
    return totals

verification_tests:
from target import total_by_category


def test_single_row():
    assert total_by_category([("food", 2500)]) == {"food": 2500}


def test_repeated_category_accumulates():
    assert total_by_category(
        [("food", 2500), ("food", 1750), ("book", 3200)]
    ) == {"food": 4250, "book": 3200}


def test_empty_rows():
    assert total_by_category([]) == {}
